// Lantern Catch: move the basket (left/right, hold the action key to hurry) under the falling
// lanterns. The score is the share of lanterns caught.
function next(s) {
  // Park-Miller: the same seed drops the same lanterns.
  s.rng = (s.rng * 16807) % 2147483647;
  return s.rng / 2147483647;
}
function drop(s) {
  s.lantern = { x: 30 + next(s) * (s.w - 60), y: -20, speed: 70 + next(s) * 50 };
  s.dropped += 1;
}
api.minigame('lantern-catch', {
  start: function (config, info) {
    var total = Math.max(1, Math.min(20, Math.floor(Number(config.lanterns) || 6)));
    var s = { w: info.width, h: info.height, x: info.width / 2, total: total, dropped: 0, caught: 0,
              rng: (info.seed % 2147483646) + 1, lantern: null, flash: 0 };
    drop(s);
    return s;
  },
  update: function (s, input, dt) {
    var speed = input.action ? 320 : 200;
    if (input.left) s.x = Math.max(40, s.x - speed * dt);
    if (input.right) s.x = Math.min(s.w - 40, s.x + speed * dt);
    s.flash = Math.max(0, s.flash - dt);
    var l = s.lantern;
    l.y += l.speed * dt;
    if (l.y >= s.h - 40) {
      if (Math.abs(l.x - s.x) <= 40) { s.caught += 1; s.flash = 0.3; }
      if (s.dropped >= s.total) return { state: s, done: { score: s.caught / s.total } };
      drop(s);
    }
    return { state: s };
  },
  draw: function (s) {
    var l = s.lantern;
    return [
      { type: 'rect', x: 0, y: 0, w: s.w, h: s.h, color: '#1b2140' },
      { type: 'rect', x: 0, y: s.h - 18, w: s.w, h: 18, color: '#2d3a5c' },
      { type: 'text', x: 12, y: 26, text: 'Caught ' + s.caught + ' / ' + s.total, size: 16, bold: true, color: '#ffe9a8' },
      { type: 'text', x: s.w - 12, y: 26, text: 'Lantern ' + s.dropped, size: 13, align: 'right', color: 'muted' },
      { type: 'rect', x: l.x - 12, y: l.y - 14, w: 24, h: 28, radius: 8, color: '#ffb347' },
      { type: 'sprite', x: l.x - 10, y: l.y - 10, w: 20, h: 20, item: 'lantern' },
      { type: 'rect', x: s.x - 40, y: s.h - 36, w: 80, h: 16, radius: 5, color: s.flash > 0 ? 'accent' : 'primary' }
    ];
  }
});
